try{const t=localStorage.getItem('futureproof:theme:v1');document.documentElement.dataset.theme=(t==='dark'||t==='light')?t:(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')}catch{document.documentElement.dataset.theme='light'}
window.addEventListener('error',function(e){if(e.target instanceof HTMLScriptElement&&e.target.src){const box=document.createElement('p');box.textContent='The app could not load. Reconnect and reload; your saved sessions will stay. ';const button=document.createElement('button');button.textContent='Reload';button.onclick=function(){location.reload()};box.append(button);document.body.append(box)}},true)
